<script lang="ts">
  import { page } from '$app/state';
  import { useDemo } from '#lib/demo.svelte';
  import { finishes, materials, phaseNames, phases, products } from '#lib/data';
  import type { Finish, Material, Phase } from '#lib/types';
  import ProductCard from '#lib/components/ProductCard.svelte';
  import Artwork from '#lib/components/Artwork.svelte';
  const demo = useDemo();
  let phase = $state(''); let surface = $state(''); let finish = $state(''); let environment = $state(''); let format = $state(''); let base = $state(''); let price = $state(''); let inStock = $state(false); let query = $state(''); let collection = $state(''); let sort = $state('popular'); let mobile = $state(false);
  $effect(() => { phase = page.url.searchParams.get('phase') ?? ''; surface = page.url.searchParams.get('material') ?? ''; query = page.url.searchParams.get('q') ?? ''; collection = page.url.searchParams.get('collection') ?? ''; base = page.url.searchParams.get('base') ?? ''; });
  const filtered = $derived(products.filter((p) => (!phase || p.phase === phase) && (!surface || p.materials.includes(surface as Material)) && (!environment || p.environments.includes(environment as 'interior' | 'exterior')) && (!base || p.base === base) && (collection !== 'new' || p.isNew) && (collection !== 'offers' || ['masilla-madera','imprimacion-madera','barniz-acrilico'].includes(p.id)) && (!query || `${p.name} ${p.variants.map((v) => `${v.color} ${v.ral ?? ''}`).join(' ')}`.toLowerCase().includes(query.toLowerCase())) && p.variants.some((v) => (!finish || v.finish === finish) && (!format || v.format === format) && (!inStock || v.stock > 0) && (!price || v.price <= Number(price)))).toSorted((a,b) => sort === 'price' ? Math.min(...a.variants.map((v) => v.price)) - Math.min(...b.variants.map((v) => v.price)) : sort === 'name' ? a.name.localeCompare(b.name) : b.popular-a.popular));
  function clear() { phase = ''; surface = ''; finish = ''; environment = ''; format = ''; base = ''; price = ''; inStock = false; query = ''; collection = ''; }
</script>
<section class="section cream"><div class="container"><div class="breadcrumb"><a href="/">{demo.t('Inicio', 'Home')}</a> / {demo.t('Productos', 'Products')}</div><h1>{demo.t('Productos WEPRO', 'WEPRO products')}</h1><p class="intro">{demo.t('De reparar a proteger. Un catálogo de muestra organizado como tu proyecto.', 'From repair to protection. A sample catalog organized like your project.')}</p><div class="grid cols-4" id="familias">{#each phases as p,i}<a class="card" href={`/productos?phase=${p}#catalogo`}><div class="card-body row between"><h3>{phaseNames[p][demo.state.language]}</h3><small>0{i+1} →</small></div><Artwork kind="product" phase={p} color={['#bf805f','#ddd7c9','#69765a','#dbba83'][i]} label={phaseNames[p][demo.state.language]}/></a>{/each}</div></div></section>
<section class="section" id="catalogo"><div class="container"><div class="row between"><h2>{phase ? phaseNames[phase as Phase]?.[demo.state.language] : demo.t('Catálogo de muestra', 'Sample catalog')}</h2><a href="/como-se-hace#comparador">{demo.t('Comparar Water / Solvent →', 'Compare Water / Solvent →')}</a></div><div class="tabs"><button class:selected={!base} onclick={() => base = ''}>{demo.t('Todas las bases', 'All bases')}</button>{#each ['Water Based','Solvent Based','Especialidades'] as b}<button class:selected={base === b} onclick={() => base = b}>{b}</button>{/each}</div><div class="filter-layout"><aside><button class="filters-mobile secondary" aria-expanded={mobile} onclick={() => mobile = !mobile}>{demo.t('Filtrar', 'Filter')}</button><div class="filters" class:visible={mobile}><div class="row between"><h3>{demo.t('Filtros', 'Filters')}</h3><button class="text-button" onclick={clear}>{demo.t('Borrar todo', 'Clear all')}</button></div><label>{demo.t('Fase', 'Phase')}<select bind:value={phase}><option value="">{demo.t('Todas', 'All')}</option>{#each phases as p}<option value={p}>{phaseNames[p][demo.state.language]}</option>{/each}<option value="tools">{demo.t('Accesorios', 'Tools')}</option></select></label><label style="margin:16px 0">{demo.t('Superficie', 'Surface')}<select bind:value={surface}><option value="">{demo.t('Todas', 'All')}</option>{#each Object.keys(materials) as m}<option value={m}>{materials[m as Material][demo.state.language]}</option>{/each}</select></label><label>{demo.t('Acabado', 'Finish')}<select bind:value={finish}><option value="">{demo.t('Todos', 'All')}</option>{#each Object.keys(finishes) as f}<option value={f}>{finishes[f as Finish][demo.state.language]}</option>{/each}</select></label><label style="margin:16px 0">{demo.t('Uso', 'Use')}<select bind:value={environment}><option value="">{demo.t('Todos', 'All')}</option><option value="interior">{demo.t('Interior', 'Indoor')}</option><option value="exterior">{demo.t('Exterior', 'Outdoor')}</option></select></label><label>{demo.t('Formato', 'Format')}<select bind:value={format}><option value="">{demo.t('Todos', 'All')}</option><option>400 ml</option><option>200 ml</option></select></label><label style="margin:16px 0">{demo.t('Precio máximo de muestra', 'Maximum sample price')}<select bind:value={price}><option value="">{demo.t('Cualquiera', 'Any')}</option><option value="1000">10 €</option><option value="1500">15 €</option><option value="2000">20 €</option></select></label><label class="check"><input type="checkbox" bind:checked={inStock}/>{demo.t('En stock demo', 'In demo stock')}</label></div></aside><div><div class="row between" style="margin-bottom:25px"><label class="grow">{demo.t('Buscar producto, color o RAL', 'Search product, color or RAL')}<input bind:value={query} placeholder="Water Based / 6003"/></label><label>{demo.t('Ordenar', 'Sort')}<select bind:value={sort}><option value="popular">{demo.t('Más vendidos demo', 'Demo best sellers')}</option><option value="price">{demo.t('Menor precio', 'Lowest price')}</option><option value="name">A → Z</option></select></label></div><p class="muted">{filtered.length} {demo.t('productos · datos de muestra', 'products · sample data')}</p>{#if collection === 'offers'}<p class="demo-note">{demo.t('Selección promocional ficticia. Usa DEMO10 en carrito para simular un 10% de descuento.', 'Fictional promotional selection. Use DEMO10 in the cart for a simulated 10% discount.')}</p>{/if}<div class="grid cols-3">{#each filtered as p}<ProductCard product={p}/>{:else}<div class="empty"><p>{demo.t('Sin resultados.', 'No results.')}</p><button onclick={clear}>{demo.t('Borrar filtros', 'Clear filters')}</button></div>{/each}</div><div class="callout row between"><p>{demo.t('Prepara tu proyecto en el orden del método.', 'Prepare your project in the method order.')}</p><a class="button secondary" href="/productos?phase=prepara#catalogo">{demo.t('Ver imprimaciones', 'View primers')}</a></div></div></div></div></section>
